// Собираем в одном месте всё, что знаем о проекте: что пришло, лист канала,
// строка проекта и шаблон канала. Все узлы ниже берут данные отсюда.
const inc = $('Разбираем входящее').first().json;
let catalog = {};
try { catalog = $('Находим лист канала').first().json || {}; } catch (e) {}
let row = {};
try { row = $('Читаем строку проекта').first().json || {}; } catch (e) {}
let tmpl = {};
try { tmpl = $('Читаем шаблоны канала').first().json || {}; } catch (e) {}

const found = !!row.sys_ProjectID && String(row.sys_ProjectID).trim() === inc.projectId;

return [{
  json: {
    ...inc,
    sheetName: String(catalog.SheetName || '').trim(),
    found,
    row: found ? row : {},
    tmpl,
    status: found ? String(row.sys_Status || '').trim() : '',
  }
}];

// Кнопка "✅" под конкретным вариантом: номер варианта приходит в самой
// кнопке, поэтому гадать, какой вариант имелся в виду, не нужно.
const ctx = $('Контекст проекта').first().json;
const row = ctx.row || {};
const n = ctx.variantNumber;
let variants = [];
try { variants = JSON.parse(row.ai_ImageVariants || '[]'); } catch (e) { variants = []; }
if (!Array.isArray(variants)) variants = [];
const found = variants.find(v => Number(v.n) === Number(n));

const cur = ctx.status;
let statusAfter = cur;
if (cur !== 'Опубликовано') {
  const same = found && found.url === String(row.ai_ApprovedImageUrl || '');
  if (!(cur === 'Утверждено' && same)) statusAfter = 'Картинка согласована';
}
const statusReverted = cur === 'Утверждено' && statusAfter !== 'Утверждено';

return [{
  json: {
    ok: !!(found && found.url),
    variantNumber: n,
    approvedUrl: found ? found.url : '',
    statusAfter,
    confirmText: `✅ Картинка согласована (вариант ${n}).` +
      (statusReverted ? '\n\n⚠️ Статус «Утверждено» снят — после смены картинки пришлю новую сводку на ✅.' : '') +
      `\n\nID: ${ctx.projectId}`,
    notFoundText: `Не нашла вариант ${n} в этом проекте — ничего не меняла.\n\nID: ${ctx.projectId}`,
    syntheticText: `[Служебное сообщение, не слова автора] Автор нажала кнопку «✅» под вариантом ${n} — это её согласование этой картинки, в таблицу оно уже записано. Вызови approve_image с variantNumber ${n} и в том же вызове передай в items все пункты текстового блока, кроме описания, и в storyBrief — задание писателю на описание.`,
  }
}];

// Сюда приходят два пути: обычная реплика автора и нажатие "✅" под
// вариантом картинки (тогда Редактору уходит служебная фраза о кнопке).
const ctx = $('Контекст проекта').first().json;
let synthetic = '';
let btn = null;
try { btn = $('Согласуем вариант').first().json; synthetic = btn.syntheticText || ''; } catch (e) {}
// После кнопки строка проекта, прочитанная в начале, уже устарела: статус и
// согласованная картинка только что записаны — берём свежие значения.
const status = btn && btn.ok ? btn.statusAfter : ctx.status;
const approvedUrl = btn && btn.ok ? btn.approvedUrl : String((ctx.row || {}).ai_ApprovedImageUrl || '').trim();

const photo = synthetic ? null : (ctx.photo && ctx.photo.length ? ctx.photo : null);
let userText = synthetic || ctx.text || '';
if (!userText.trim()) userText = photo ? '(фото без подписи)' : '(пустое сообщение)';

return [{
  json: {
    projectId: ctx.projectId,
    chatId: ctx.chatId,
    sheetName: ctx.sheetName,
    channelKey: ctx.channelKey,
    userText,
    photo,
    fromButton: !!synthetic,
    status,
    approvedUrl,
  }
}];

