// ── конец общего куска ─────────────────────────────────────────────────────

// База канала из таблицы Templates: все колонки со значками 🖋 и 🎨.
// Новая колонка с тем же значком попадёт сюда сама, без правки кода.
const ctx = $('Контекст проекта').first().json;
const tmpl = ctx.tmpl || {};
if (!tmpl || !Object.keys(tmpl).length) {
  throw new Error('Шаблон для канала ' + ctx.channelKey + ' не найден в Templates');
}

function stripLabel(key) { return key.replace(/^[^a-zA-Z]+/, ''); }

function extractSection(text, tag) {
  if (!text) return '';
  const re = new RegExp('###' + tag + '###([\\s\\S]*?)###/' + tag + '###');
  const m = text.match(re);
  return m ? m[1].trim() : '';
}

// Google Drive отдаёт HTML-страницу на обычной ссылке — приводим к прямой.
function toDirectImageUrl(url) {
  const match = url.match(/\/d\/([a-zA-Z0-9_-]+)/) || url.match(/[?&]id=([a-zA-Z0-9_-]+)/);
  return match ? 'https://lh3.googleusercontent.com/d/' + match[1] + '=s2000' : url;
}

const textParts = [];
const imageUrls = [];
// Роль картинки — строка, написанная в ячейке сразу под её ссылкой (например,
// «манера и размер героя в кадре»). Художнику уходит «Image N — роль».
const imageRoles = [];
const urlLine = /^https?:\/\/\S+$/;
for (const key of Object.keys(tmpl)) {
  if (key.includes('tmpl_SystemPrompt')) continue;
  if (!key.includes('🖋') && !key.includes('🎨')) continue;
  const value = String(tmpl[key] || '');
  const lines = value.split('\n');
  const keep = [];
  let lastImage = -1;
  for (const line of lines) {
    const t = line.trim();
    if (urlLine.test(t)) {
      if (key.includes('🎨')) { imageUrls.push(toDirectImageUrl(t)); imageRoles.push(''); lastImage = imageUrls.length - 1; }
    } else {
      if (t && lastImage >= 0 && !imageRoles[lastImage]) imageRoles[lastImage] = t;
      else if (t) lastImage = -1;
      keep.push(line);
    }
  }
  const text = keep.join('\n').trim();
  if (text) textParts.push(stripLabel(key) + ':\n' + text);
}

// Все три раздела SystemPrompt — теперь это один Редактор на все этапы.
const spKey = Object.keys(tmpl).find(k => k.includes('tmpl_SystemPrompt'));
const sp = spKey ? String(tmpl[spKey] || '') : '';
const sections = [
  ['КАРТИНКА', 'этап картинки'],
  ['ОПИСАНИЕ', 'описание'],
  ['ТЕХНИЧЕСКОЕ', 'техническая часть: оверлей, название, подвал, хэштеги, теги'],
].map(([tag, label]) => {
  const body = extractSection(sp, tag);
  return body ? `SystemPrompt (${label}):\n${body}` : '';
}).filter(Boolean);

const knowledgeText = [...sections, ...textParts].join('\n\n');

// Правила перевода описания — тоже из таблицы (раздел ###ПЕРЕВОД### в SystemPrompt).
const translationRules = extractSection(sp, 'ПЕРЕВОД');

let timecodeCount = parseInt(findByLabel(tmpl, 'tmpl_TimecodeCount'), 10);
if (!timecodeCount || timecodeCount < 1) timecodeCount = 25;

// Роли референсов для художника. Рисование: Image 1.. = референсы по порядку.
// Правка: Image 1 = текущая картинка, референсы сдвигаются на один.
const MAX_REFS = 5;
function rolesText(shift) {
  const parts = imageRoles.slice(0, MAX_REFS)
    .map((r, i) => (r ? `Image ${i + 1 + shift} — ${r}.` : ''))
    .filter(Boolean);
  return parts.length ? 'Reference images: ' + parts.join(' ') + '\n\n' : '';
}
const referenceRolesDraw = rolesText(0);
const referenceRolesEdit = rolesText(1);
// Модель художника — из таблицы (колонка tmpl_ImageModel); пусто — прежняя.
const imageModel = String(findByLabel(tmpl, 'tmpl_ImageModel') || '').trim() || 'gpt-image-2';

const vectorStoreId = String(findByLabel(tmpl, 'tmpl_ChannelVectorStoreId') || '').trim();
const characterPassport = String(findByLabel(tmpl, 'tmpl_CharacterPassport') || '').trim();
// Писателю — только то, что нужно для истории (правила описания, мир Пингви, заметки о стиле).
const writerRules = extractSection(sp, 'ОПИСАНИЕ');
const writerWorld = ['tmpl_ProjectContext', 'tmpl_CharacterPassport', 'tmpl_LocationPassports', 'tmpl_Chronicle', 'tmpl_EditorNotes']
  .map(label => {
    const key = Object.keys(tmpl).find(k => k.includes(label));
    const v = key ? String(tmpl[key] || '').trim() : '';
    return v ? stripLabel(key) + ':\n' + v : '';
  }).filter(Boolean).join('\n\n');

return [{
  json: {
    knowledgeText,
    styleGuideUrl: imageUrls[0] || null,
    referenceUrls: imageUrls.slice(1),
    timecodeCount,
    vectorStoreId,
    characterPassport,
    writerRules,
    referenceRolesDraw,
    referenceRolesEdit,
    imageModel,
    writerWorld,
    translationRules,
  }
}];

// Фото автора → data URL, чтобы Редактор увидел саму картинку.
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const item = $input.first();
let mimeType = (item.binary && item.binary.data && item.binary.data.mimeType) || '';
if (!mimeType || mimeType === 'application/octet-stream') mimeType = 'image/jpeg';
return [{ json: { userImageUrl: `data:${mimeType};base64,${buffer.toString('base64')}` } }];

// ── Общий кусок (одинаковый в нескольких узлах этого канваса) ──────────────
// Текстовый блок: 8 пунктов с ЖЁСТКО закреплёнными номерами. Номер никогда
// не переприсваивается: 3 — это всегда "Описание".
const TB_ITEMS = [
  { n: 1, name: 'Оверлей', keys: ['overlayText', 'overlayPosition'] },
  { n: 2, name: 'Название', keys: ['title'] },
  { n: 3, name: 'Описание', keys: ['description'] },
  { n: 4, name: 'Тайм-коды', keys: ['timecodes'] },
  { n: 5, name: 'Подвал', keys: ['footer'] },
  { n: 6, name: 'Хэштеги', keys: ['hashtags'] },
  { n: 7, name: 'Теги', keys: ['tags'] },
  { n: 8, name: 'Закреплённый комментарий', keys: ['pinnedComment'] },
];
// Пункты, которые можно осознанно оставить пустыми (например, гайд без оверлея).
const TB_CAN_BE_EMPTY = [1, 8];

function tbEmptyState() {
  return {
    v: 1,
    items: { overlayText: '', overlayPosition: '', title: '', description: '', timecodes: [], footer: '', hashtags: '', tags: '', pinnedComment: '' },
    set: {},
    agreed: {},
    descriptionEN: '',
    descriptionENFor: '',
    seenImages: [],
    ru: {},
  };
}

function tbParseState(raw) {
  const s = tbEmptyState();
  if (!raw) return s;
  let p;
  try { p = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { return s; }
  if (!p || typeof p !== 'object') return s;
  Object.assign(s.items, p.items || {});
  if (!Array.isArray(s.items.timecodes)) s.items.timecodes = [];
  s.set = p.set || {};
  s.agreed = p.agreed || {};
  s.descriptionEN = p.descriptionEN || '';
  s.descriptionENFor = p.descriptionENFor || '';
  s.seenImages = Array.isArray(p.seenImages) ? p.seenImages : [];
  s.ru = (p.ru && typeof p.ru === 'object') ? p.ru : {};
  return s;
}

function tbAllAgreed(s) {
  return TB_ITEMS.every(it => s.agreed[it.n] === true);
}

function tbPositionRu(p) {
  return { left: 'слева', right: 'справа', center: 'по центру' }[String(p || '').toLowerCase()] || (p || '');
}

// Текст одного пункта для показа автору (без номера и названия).
// Русский перевод (state.ru) показывается рядом в скобках — только автору;
// в таблицу и на YouTube уходит лишь сам текст пункта (state.items).
function tbItemText(s, n) {
  const it = s.items;
  const ru = s.ru || {};
  const tr = (v) => (v ? ` (${v})` : '');
  switch (n) {
    case 1:
      if (!s.set[1]) return '';
      return it.overlayText ? `${it.overlayText}${tr(ru.overlayText)} — ${tbPositionRu(it.overlayPosition) || 'позиция не указана'}` : '— без оверлея';
    case 2: return it.title ? it.title + tr(ru.title) : '';
    case 3: return (it.description || '') + (it.description && ru.description ? `\n\n— Перевод для автора —\n${ru.description}` : '');
    case 4: return (it.timecodes || []).map((t, i) => `${i + 1}. ${t}${tr((ru.timecodes || [])[i])}`).join('\n');
    case 5: return it.footer || '';
    case 6: return it.hashtags || '';
    case 7: return it.tags || '';
    case 8:
      if (!s.set[8]) return '';
      return it.pinnedComment ? it.pinnedComment + (ru.pinnedComment ? `\n(${ru.pinnedComment})` : '') : '— без закреплённого комментария';
  }
  return '';
}

function escapeHtml(t) {
  return String(t == null ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// Режем длинный текст на куски под лимит Телеграма (4096), стараясь по переносу строки.
function splitForTelegram(text, limit) {
  const LIMIT = limit || 3800;
  const chunks = [];
  let rest = String(text || '');
  while (rest.length > LIMIT) {
    let cut = rest.lastIndexOf('\n', LIMIT);
    if (cut < LIMIT * 0.5) cut = LIMIT;
    chunks.push(rest.slice(0, cut));
    rest = rest.slice(cut).replace(/^\n+/, '');
  }
  if (rest.length) chunks.push(rest);
  if (!chunks.length) return [''];
  // ID проекта — в КАЖДОЙ части: автор может ответить (reply) на любую.
  const idm = String(text || '').match(/\n\nID: (\S+)\s*$/);
  if (idm && chunks.length > 1) {
    for (let i = 0; i < chunks.length - 1; i++) chunks[i] += `\n\n(продолжение ниже)\nID: ${idm[1]}`;
  }
  return chunks;
}

function findByLabel(row, label) {
  const key = Object.keys(row || {}).find(k => k.replace(/^[^a-zA-Z]+/, '') === label);
  return key ? row[key] : undefined;
}

// Барьер перед сборщиком: проверяем то, что РЕАЛЬНО лежит в таблице (строку
// перечитываем заново перед проверкой), а не то, что мы "вроде бы записали".
function validateForAssembler(row, tmpl, opts) {
  const o = opts || {};
  const problems = [];
  const val = k => String(row[k] == null ? '' : row[k]).trim();

  let required = ['overlayPosition', 'title', 'hashtags', 'tags', 'description'];
  const rawReq = findByLabel(tmpl, 'tmpl_RequiredTechFields');
  if (rawReq && String(rawReq).trim()) {
    required = String(rawReq).split(',').map(x => x.trim()).filter(Boolean);
  }
  const colFor = {
    overlayText: 'ai_OverlayText', overlayPosition: 'ai_OverlayPosition', title: 'ai_Title',
    hashtags: 'ai_Hashtags', tags: 'ai_Tags', description: 'ai_Description', pinnedComment: 'ai_PinnedComment',
  };
  for (const key of required) {
    const col = colFor[key] || key;
    if (!val(col)) problems.push(`${col} пустая`);
  }
  if (!val('ai_ApprovedImageUrl')) problems.push('ai_ApprovedImageUrl пустая (нет согласованной картинки)');
  if (!val('ai_DescriptionEN')) problems.push('ai_DescriptionEN пустая (нет английского описания)');
  if (val('ai_Description') && !/\[?Timecodes\]?/i.test(val('ai_Description'))) {
    problems.push('в ai_Description нет метки [Timecodes]');
  }
  if (o.needApproved && val('sys_Status') !== 'Утверждено') {
    problems.push(`статус «${val('sys_Status') || 'пусто'}», а не «Утверждено»`);
  }
  if (o.needTracks && !val('sys_AudioZipUrl')) problems.push('sys_AudioZipUrl пустая (нет ссылки на треки)');
  return problems;
}
// ── конец общего куска ─────────────────────────────────────────────────────

const ctx = $('Контекст проекта').first().json;
const vhod = $('Вход редактора').first().json;
const kb = $('Собираем знания канала').first().json;
let prevText = '';
try { prevText = $('Прошлые главы').first().json.text || ''; } catch (e) {}
const row = ctx.row || {};
const state = tbParseState(row.sys_EditorState);

// Разговор: либо уже есть у проекта, либо только что создан.
let conversationId = String(row.sys_ConversationId || '').trim();
let isNewConversation = false;
if (!conversationId) {
  try { conversationId = $('OpenAI: создаём разговор').first().json.id; isNewConversation = true; } catch (e) {}
}
if (!conversationId) throw new Error('Нет conversation_id для проекта ' + ctx.projectId);
const pendingCallId = isNewConversation ? '' : String(row.sys_PendingToolCallId || '').trim();

let userImageUrl = '';
try { userImageUrl = $('Фото в base64').first().json.userImageUrl || ''; } catch (e) {}

// ── Варианты картинки ──
let variants = [];
try { variants = JSON.parse(row.ai_ImageVariants || '[]'); } catch (e) { variants = []; }
if (!Array.isArray(variants)) variants = [];
const approvedUrl = vhod.approvedUrl;
const approvedVariant = variants.find(v => v.url === approvedUrl);

// ── Какие картинки показать модели в этом ходе ──
// Всё, что модель уже видела в этом разговоре, остаётся в его истории —
// повторно не прикладываем (иначе разговор разбухает от одних и тех же
// картинок). Прикладываем только новое: свежее фото автора, новые варианты,
// а на первом ходе — style guide и референсы канала.
const seen = new Set(state.seenImages || []);
const images = [];
function addImage(url, label) {
  if (!url || seen.has(url)) return;
  images.push({ url, label });
  seen.add(url);
}
if (kb.styleGuideUrl) addImage(kb.styleGuideUrl, 'style guide канала');
(kb.referenceUrls || []).forEach((u, i) => addImage(u, 'референс канала ' + (i + 1)));
variants.forEach(v => addImage(v.url, 'вариант ' + v.n + ' этого проекта'));
if (approvedUrl && !approvedVariant) addImage(approvedUrl, 'согласованная картинка этого проекта');

// ── Карточка состояния проекта: единственный источник правды ──
function line(s) { return s; }
const variantLines = variants.length
  ? variants.map(v => `  • Вариант ${v.n}${approvedVariant && approvedVariant.n === v.n ? ' — СОГЛАСОВАН' : ''}: ${(v.dallePrompt || '').slice(0, 300)}`).join('\n')
  : '  (ещё ни одного варианта)';
const tbLines = TB_ITEMS.map(it => {
  const status = state.agreed[it.n] ? 'СОГЛАСОВАНО' : (state.set[it.n] ? 'предложено, ждёт согласования' : 'ещё не предлагалось');
  const text = tbItemText(state, it.n);
  return `  ${it.n}. ${it.name} [${status}]` + (text ? `\n${text.split('\n').map(l => '     ' + l).join('\n')}` : '');
}).join('\n');

const stateCard = [
  `Проект ${ctx.projectId}, статус в таблице: «${vhod.status || 'пусто'}».`,
  `Картинка: ${approvedUrl ? 'согласована' + (approvedVariant ? ' (вариант ' + approvedVariant.n + ')' : '') : 'ещё НЕ согласована'}.`,
  'Варианты:',
  variantLines,
  '',
  'Текстовый блок:',
  tbLines,
  '',
  `Нужное число тайм-кодов (из таблицы): ${kb.timecodeCount}.`,
  `Ссылка на треки: ${String(row.sys_AudioZipUrl || '').trim() ? 'уже прислана' : 'ещё не прислана'}.`,
  row.ai_UserBrief ? `Изначальный бриф автора: ${row.ai_UserBrief}` : '',
].filter(x => x !== '').join('\n');

const instructions = `Ты — редактор канала "${ctx.sheetName}". Ты ведёшь весь выпуск в одном разговоре с автором: картинку и текстовый блок. Как говорить, что и как писать — всё это правила канала в базе ниже (SystemPrompt по этапам, паспорта, правила упаковки, заметки). Здесь — только то, как устроена сама система.

КАК УСТРОЕН ВЫПУСК
Картинка → текстовый блок из 8 пунктов → автор жмёт финальную кнопку "✅ Согласовано" под сводкой → всё записывается в таблицу → когда придёт ссылка на треки, видео собирается автоматически. Между этапами можно двигаться свободно в любую сторону, по смыслу слов автора — кодовых слов и переключений нет.

КАРТОЧКА СОСТОЯНИЯ (в самом конце) — источник правды о том, что нарисовано, согласовано и записано; обновляется перед каждым твоим ответом. Если она расходится с тем, что ты помнишь из разговора, — верь карточке.

ИНСТРУМЕНТЫ. За один ответ — не больше одного инструмента; если ничего не нужно — просто отвечай текстом.
- start_drawing — нарисовать НОВЫЙ пронумерованный вариант. Художник получает ровно твоё описание сцены и референсы канала из таблицы.
- request_revision — правка уже нарисованного варианта. Результат сохраняется следующим вариантом, прежний остаётся. Художник получает ровно твоё описание правки, текущую картинку (как основу) и референсы канала. Если вариантов несколько и неясно, какой правим, — уточни номер.
- approve_image — автор согласовала картинку. В ЭТОМ ЖЕ вызове сразу передай в items все пункты текстового блока, кроме описания, а в storyBrief — задание писателю на описание; автор получит подтверждение и первый вариант текста одним сообщением. Если вариантов несколько и номер не прозвучал — переспроси. Под каждой картинкой у автора своя кнопка "✅"; если она её нажала, придёт служебное сообщение — тогда вызови approve_image с этим номером и тоже сразу с items и storyBrief.
- commission_story — заказать писателю описание (пункт 3): новое или переписанное. Описание пишет только писатель — сам ты его не пишешь и не правишь, любые пожелания автора к описанию передаёшь ему этим инструментом. Писатель получает правила канала для описания, паспорта, заметки, прошлые главы, согласованную картинку и твоё задание — больше ничего, прежний текст он не видит. В storyBrief — ситуация и чувство, а не план по пунктам: о чём этот выпуск, мелодия и её история, что происходит на картинке, и слова автора о тексте, если она что-то сказала; историю писатель находит сам. Если автор похвалила что-то в прежнем тексте — перенеси это в keepFromPrevious.
- update_text_block — предложить, изменить или отметить согласованными пункты текстового блока.
- update_communication_notes — сохранить заметки в базу канала (колонка EditorNotes). Передавай ПОЛНЫЙ обновлённый текст заметок: существующие + новое.
Если по смыслу твоих слов что-то согласовано, начато или изменено, а инструмент не вызван — вызови его в этом же ответе.
Если правила канала противоречат друг другу — скажи об этом автору, чтобы она поправила таблицу.

ТЕКСТОВЫЙ БЛОК: 8 ПУНКТОВ, НОМЕРА ЗАКРЕПЛЕНЫ
1. Оверлей (текст + позиция left/right/center). 2. Название. 3. Описание. 4. Тайм-коды. 5. Подвал. 6. Хэштеги. 7. Теги. 8. Закреплённый комментарий.
Содержание, язык и стиль каждого пункта — по правилам канала в базе ниже. Технические требования системы:
- Оверлей или закреплённый комментарий не нужны — передай "-".
- Тайм-кодов — ровно столько, сколько указано в карточке.
- Подвал обязательно содержит буквальную метку [Timecodes] — туда сборщик вставит тайм-коды.
- Описание пишет писатель — на языке оригинала по правилам канала; автору система сама показывает перевод рядом.
- К оверлею, названию, тайм-кодам и закреплённому комментарию передавай в ruTranslations русский перевод — система покажет его автору в скобках рядом; в таблицу и на YouTube он не идёт.
Как работать с блоком:
- После update_text_block система сама покажет автору пронумерованные пункты, ждущие согласования, — в messageToUser их не переписывай.
- В items — только пункты, которые предлагаешь или меняешь сейчас (пустая строка = без изменений). Изменённый пункт снова ждёт согласования.
- В agreedItems — ТОЛЬКО номера пунктов, которые автор явно одобрила (по номеру, названию или общим «всё ок» — тогда все показанные). Передумала насчёт согласованного — в reopenItems.
- Когда согласованы все 8, система сама пришлёт сводку с одной кнопкой "✅ Согласовано". Показать блок или сводку заново — update_text_block без изменений.
- Правка после "Утверждено" снимает этот статус; система предупредит автора.

КАРТИНКИ В ЭТОМ РАЗГОВОРЕ
Вместе с сообщениями тебе показываются настоящие картинки: фото автора (если прислала), style guide и референсы канала, новые варианты этого проекта. Каждая показывается один раз и дальше остаётся в истории разговора.

БАЗА КАНАЛА (персонаж, локации, стиль, правила упаковки, заметки — используй по смыслу подписи каждого блока):
${kb.knowledgeText}
${prevText ? `

ПРОШЛЫЕ ГЛАВЫ — последние выпуски канала, как их согласовала автор (для сквозных нитей и продолжения голоса; сюжеты не повторяй, но можешь опереться на них: то, что было раньше, продолжается). Старые выпуски можно найти поиском по памяти канала (file_search).
${prevText}` : ''}

КАРТОЧКА СОСТОЯНИЯ ПРОЕКТА (актуальна на этот ход):
${stateCard}`;

