// ── Общий кусок (одинаковый в нескольких узлах этого канваса) ──────────────
// Текстовый блок: 8 пунктов с ЖЁСТКО закреплёнными номерами. Номер никогда
// не переприсваивается: 3 — это всегда "Описание".
const TB_ITEMS = [
  { n: 1, name: 'Оверлей', keys: ['overlayText', 'overlayPosition'] },
  { n: 2, name: 'Название', keys: ['title'] },
  { n: 3, name: 'Описание', keys: ['description'] },
  { n: 4, name: 'Тайм-коды', keys: ['timecodes'] },
  { n: 5, name: 'Подвал', keys: ['footer'] },
  { n: 6, name: 'Хэштеги', keys: ['hashtags'] },
  { n: 7, name: 'Теги', keys: ['tags'] },
  { n: 8, name: 'Закреплённый комментарий', keys: ['pinnedComment'] },
];
// Пункты, которые можно осознанно оставить пустыми (например, гайд без оверлея).
const TB_CAN_BE_EMPTY = [1, 8];

function tbEmptyState() {
  return {
    v: 1,
    items: { overlayText: '', overlayPosition: '', title: '', description: '', timecodes: [], footer: '', hashtags: '', tags: '', pinnedComment: '' },
    set: {},
    agreed: {},
    descriptionEN: '',
    descriptionENFor: '',
    seenImages: [],
    ru: {},
  };
}

function tbParseState(raw) {
  const s = tbEmptyState();
  if (!raw) return s;
  let p;
  try { p = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { return s; }
  if (!p || typeof p !== 'object') return s;
  Object.assign(s.items, p.items || {});
  if (!Array.isArray(s.items.timecodes)) s.items.timecodes = [];
  s.set = p.set || {};
  s.agreed = p.agreed || {};
  s.descriptionEN = p.descriptionEN || '';
  s.descriptionENFor = p.descriptionENFor || '';
  s.seenImages = Array.isArray(p.seenImages) ? p.seenImages : [];
  s.ru = (p.ru && typeof p.ru === 'object') ? p.ru : {};
  return s;
}

function tbAllAgreed(s) {
  return TB_ITEMS.every(it => s.agreed[it.n] === true);
}

function tbPositionRu(p) {
  return { left: 'слева', right: 'справа', center: 'по центру' }[String(p || '').toLowerCase()] || (p || '');
}

// Текст одного пункта для показа автору (без номера и названия).
// Русский перевод (state.ru) показывается рядом в скобках — только автору;
// в таблицу и на YouTube уходит лишь сам текст пункта (state.items).
function tbItemText(s, n) {
  const it = s.items;
  const ru = s.ru || {};
  const tr = (v) => (v ? ` (${v})` : '');
  switch (n) {
    case 1:
      if (!s.set[1]) return '';
      return it.overlayText ? `${it.overlayText}${tr(ru.overlayText)} — ${tbPositionRu(it.overlayPosition) || 'позиция не указана'}` : '— без оверлея';
    case 2: return it.title ? it.title + tr(ru.title) : '';
    case 3: return (it.description || '') + (it.description && ru.description ? `\n\n— Перевод для автора —\n${ru.description}` : '');
    case 4: return (it.timecodes || []).map((t, i) => `${i + 1}. ${t}${tr((ru.timecodes || [])[i])}`).join('\n');
    case 5: return it.footer || '';
    case 6: return it.hashtags || '';
    case 7: return it.tags || '';
    case 8:
      if (!s.set[8]) return '';
      return it.pinnedComment ? it.pinnedComment + (ru.pinnedComment ? `\n(${ru.pinnedComment})` : '') : '— без закреплённого комментария';
  }
  return '';
}

function escapeHtml(t) {
  return String(t == null ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// Режем длинный текст на куски под лимит Телеграма (4096), стараясь по переносу строки.
function splitForTelegram(text, limit) {
  const LIMIT = limit || 3800;
  const chunks = [];
  let rest = String(text || '');
  while (rest.length > LIMIT) {
    let cut = rest.lastIndexOf('\n', LIMIT);
    if (cut < LIMIT * 0.5) cut = LIMIT;
    chunks.push(rest.slice(0, cut));
    rest = rest.slice(cut).replace(/^\n+/, '');
  }
  if (rest.length) chunks.push(rest);
  if (!chunks.length) return [''];
  // ID проекта — в КАЖДОЙ части: автор может ответить (reply) на любую.
  const idm = String(text || '').match(/\n\nID: (\S+)\s*$/);
  if (idm && chunks.length > 1) {
    for (let i = 0; i < chunks.length - 1; i++) chunks[i] += `\n\n(продолжение ниже)\nID: ${idm[1]}`;
  }
  return chunks;
}

function findByLabel(row, label) {
  const key = Object.keys(row || {}).find(k => k.replace(/^[^a-zA-Z]+/, '') === label);
  return key ? row[key] : undefined;
}

// Барьер перед сборщиком: проверяем то, что РЕАЛЬНО лежит в таблице (строку
// перечитываем заново перед проверкой), а не то, что мы "вроде бы записали".
function validateForAssembler(row, tmpl, opts) {
  const o = opts || {};
  const problems = [];
  const val = k => String(row[k] == null ? '' : row[k]).trim();

  let required = ['overlayPosition', 'title', 'hashtags', 'tags', 'description'];
  const rawReq = findByLabel(tmpl, 'tmpl_RequiredTechFields');
  if (rawReq && String(rawReq).trim()) {
    required = String(rawReq).split(',').map(x => x.trim()).filter(Boolean);
  }
  const colFor = {
    overlayText: 'ai_OverlayText', overlayPosition: 'ai_OverlayPosition', title: 'ai_Title',
    hashtags: 'ai_Hashtags', tags: 'ai_Tags', description: 'ai_Description', pinnedComment: 'ai_PinnedComment',
  };
  for (const key of required) {
    const col = colFor[key] || key;
    if (!val(col)) problems.push(`${col} пустая`);
  }
  if (!val('ai_ApprovedImageUrl')) problems.push('ai_ApprovedImageUrl пустая (нет согласованной картинки)');
  if (!val('ai_DescriptionEN')) problems.push('ai_DescriptionEN пустая (нет английского описания)');
  if (val('ai_Description') && !/\[?Timecodes\]?/i.test(val('ai_Description'))) {
    problems.push('в ai_Description нет метки [Timecodes]');
  }
  if (o.needApproved && val('sys_Status') !== 'Утверждено') {
    problems.push(`статус «${val('sys_Status') || 'пусто'}», а не «Утверждено»`);
  }
  if (o.needTracks && !val('sys_AudioZipUrl')) problems.push('sys_AudioZipUrl пустая (нет ссылки на треки)');
  return problems;
}
// ── конец общего куска ─────────────────────────────────────────────────────

const response = $input.first().json;
const prep = $('Готовим запрос редактору').first().json;
const ctx = $('Контекст проекта').first().json;
const kb = $('Собираем знания канала').first().json;
const vhod = $('Вход редактора').first().json;
const row = ctx.row || {};
const output = response.output || [];

// Текст ответа (может быть несколько частей) и вызов инструмента — это
// отдельные элементы output, никакого разбора регулярками.
const plainText = output
  .filter(i => i.type === 'message')
  .flatMap(i => (i.content || []).filter(c => c.type === 'output_text').map(c => c.text))
  .join('\n\n')
  .trim();
const callItem = output.find(i => i.type === 'function_call');

let action = 'chat';
let messageToUser = plainText;
let callId = null;
let functionName = null;
let args = {};
if (callItem) {
  callId = callItem.call_id;
  functionName = callItem.name;
  try { args = JSON.parse(callItem.arguments || '{}'); } catch (e) { args = {}; }
  messageToUser = args.messageToUser || plainText || '';
}

const state = tbParseState(row.sys_EditorState);
state.seenImages = prep.newSeenImages || state.seenImages;

let variants = [];
try { variants = JSON.parse(row.ai_ImageVariants || '[]'); } catch (e) { variants = []; }
if (!Array.isArray(variants)) variants = [];
const lastVariant = variants.length ? variants[variants.length - 1] : null;

let dallePrompt = '';
let revisionInstruction = '';
let revisionIsNewVariant = false;
let revisionTargetImageUrl = String(row.ai_ImageUrl || '');
let revisionTargetVariantNumber = lastVariant ? lastVariant.n : 1;
let approveVariantNumber = null;
let approveTargetBrightness = null;
let resolvedApprovedImageUrl = '';
let communicationNotes = '';
let storyBrief = '';
let storyKeep = '';
const changedItems = [];
let textBlockTouched = false;

function applyTextBlock(args) {
  const items = args.items || {};
  const setVal = (key, n, value) => {
    const old = state.items[key];
    const same = Array.isArray(value) ? JSON.stringify(old) === JSON.stringify(value) : old === value;
    const wasSet = !!state.set[n];
    state.set[n] = true;
    if (!same || !wasSet) {
      state.items[key] = value;
      if (!changedItems.includes(n)) changedItems.push(n);
      state.agreed[n] = false;
    }
  };
  const str = v => (typeof v === 'string' ? v.trim() : '');
  // Пункт 1: текст и позиция живут вместе.
  if (str(items.overlayText)) setVal('overlayText', 1, str(items.overlayText) === '-' ? '' : str(items.overlayText));
  if (str(items.overlayPosition)) setVal('overlayPosition', 1, str(items.overlayPosition).toLowerCase());
  if (str(items.title)) setVal('title', 2, str(items.title));
  // Пункт 3 (описание) пишет только Писатель — через storyBrief, не здесь.
  let tc = items.timecodes;
  if (typeof tc === 'string') tc = tc.split('\n');
  if (Array.isArray(tc)) {
    tc = tc.map(x => String(x || '').replace(/^\s*\d+[.)]\s*/, '').trim()).filter(Boolean);
    if (tc.length) setVal('timecodes', 4, tc);
  }
  if (str(items.footer)) setVal('footer', 5, str(items.footer));
  if (str(items.hashtags)) setVal('hashtags', 6, str(items.hashtags));
  if (str(items.tags)) setVal('tags', 7, str(items.tags));
  if (str(items.pinnedComment)) setVal('pinnedComment', 8, str(items.pinnedComment) === '-' ? '' : str(items.pinnedComment));

  // Русский перевод для автора: новый — сохраняем; если пункт изменился,
  // а перевода к нему не прислали — старый перевод убираем (он устарел).
  const ru = args.ruTranslations || {};
  state.ru = state.ru || {};
  for (const [key, n] of [['overlayText', 1], ['title', 2], ['pinnedComment', 8]]) {
    if (typeof ru[key] === 'string' && ru[key].trim()) state.ru[key] = ru[key].trim();
    else if (changedItems.includes(n)) delete state.ru[key];
  }
  if (Array.isArray(ru.timecodes) && ru.timecodes.length) state.ru.timecodes = ru.timecodes.map(x => String(x || '').replace(/^\s*\d+[.)]\s*/, '').trim());
  else if (changedItems.includes(4)) delete state.ru.timecodes;

  // Английский перевод относится к конкретному тексту описания.
  if (state.descriptionENFor !== state.items.description) {
    state.descriptionEN = '';
    state.descriptionENFor = '';
  }

  for (const n of (args.reopenItems || [])) {
    if (state.agreed[n]) { state.agreed[n] = false; if (!changedItems.includes(n)) changedItems.push(n); }
  }
  for (const raw of (args.agreedItems || [])) {
    const n = parseInt(raw, 10);
    if (!(n >= 1 && n <= 8)) continue;
    if (!state.set[n] && TB_CAN_BE_EMPTY.includes(n)) state.set[n] = true; // "оверлей/коммент не нужен"
    if (state.set[n]) state.agreed[n] = true;
  }
}

if (functionName === 'start_drawing') {
  action = 'ready_to_draw';
  dallePrompt = args.dallePrompt || '';
  if (!dallePrompt.trim()) action = 'chat';
} else if (functionName === 'request_revision') {
  action = 'revise_point';
  revisionInstruction = args.revisionInstruction || '';
  // Правка всегда сохраняется новым вариантом: удачная картинка не теряется из-за неудачной правки.
  revisionIsNewVariant = true;
  const target = args.variantNumber ? variants.find(v => Number(v.n) === Number(args.variantNumber)) : null;
  if (target && target.url) {
    revisionTargetImageUrl = target.url;
    revisionTargetVariantNumber = target.n;
  }
  if (!revisionTargetImageUrl) action = 'chat';
} else if (functionName === 'approve_image') {
  action = 'approved';
  approveVariantNumber = args.variantNumber || null;
  approveTargetBrightness = args.targetBrightness || null;
  const found = approveVariantNumber ? variants.find(v => Number(v.n) === Number(approveVariantNumber)) : null;
  resolvedApprovedImageUrl = (found && found.url) || (variants.length === 1 ? variants[0].url : '') || String(row.ai_ImageUrl || '');
  if (!resolvedApprovedImageUrl) action = 'chat';
  // Вместе с согласованием Редактор сразу присылает первый вариант текста.
  if (action === 'approved' && args.items && Object.keys(args.items).length) {
    textBlockTouched = true;
    applyTextBlock(args);
  }
  if (action === 'approved') storyBrief = String(args.storyBrief || '').trim();
} else if (functionName === 'commission_story') {
  action = 'text_block';
  textBlockTouched = true;
  storyBrief = String(args.storyBrief || '').trim();
  storyKeep = String(args.keepFromPrevious || '').trim();
  if (!storyBrief) action = 'chat';
} else if (functionName === 'update_communication_notes') {
  communicationNotes = args.notes || '';
} else if (functionName === 'update_text_block') {
  action = 'text_block';
  textBlockTouched = true;
  applyTextBlock(args);
}

// ── Статус в таблице ──
// Статус больше НЕ управляет разговором — он нужен только как стена перед
// сборщиком. Любая правка текста после "Утверждено" снимает утверждение.
const curStatus = vhod.status;
let statusAfter = curStatus || 'Картинка в работе';
let statusReverted = false;
if (curStatus !== 'Опубликовано') {
  if (action === 'approved') {
    const sameAsApproved = resolvedApprovedImageUrl && resolvedApprovedImageUrl === vhod.approvedUrl;
    if (!(curStatus === 'Утверждено' && sameAsApproved)) statusAfter = 'Картинка согласована';
  }
  if (curStatus === 'Утверждено' && action === 'text_block' && changedItems.length) {
    statusAfter = 'Картинка согласована';
  }
  statusReverted = curStatus === 'Утверждено' && statusAfter !== 'Утверждено';
}

return [{
  json: {
    action,
    functionName,
    approvedNow: action === 'approved',
    messageToUser,
    callId,
    conversationId: prep.conversationId,
    editorState: JSON.stringify(state),
    statusAfter,
    statusReverted,
    changedItems,
    textBlockTouched,
    allAgreed: tbAllAgreed(state),
    communicationNotes,
    storyBrief,
    storyKeep,
    userBrief: String(row.ai_UserBrief || '').trim() || (vhod.fromButton ? '' : vhod.userText),
    // для веток рисования (узлы перенесены из 01_Художник без изменений)
    dallePrompt,
    revisionInstruction,
    revisionIsNewVariant,
    revisionTargetImageUrl,
    revisionTargetVariantNumber,
    approveVariantNumber,
    approveTargetBrightness,
    resolvedApprovedImageUrl,
    styleGuideUrl: kb.styleGuideUrl,
    referenceUrls: kb.referenceUrls,
    fromButton: vhod.fromButton,
    projectId: ctx.projectId,
    chatId: ctx.chatId,
    sheetName: ctx.sheetName,
    channelKey: ctx.channelKey,
  }
}];

// ── Общий кусок (одинаковый в нескольких узлах этого канваса) ──────────────
// Текстовый блок: 8 пунктов с ЖЁСТКО закреплёнными номерами. Номер никогда
// не переприсваивается: 3 — это всегда "Описание".
const TB_ITEMS = [
  { n: 1, name: 'Оверлей', keys: ['overlayText', 'overlayPosition'] },
  { n: 2, name: 'Название', keys: ['title'] },
  { n: 3, name: 'Описание', keys: ['description'] },
  { n: 4, name: 'Тайм-коды', keys: ['timecodes'] },
  { n: 5, name: 'Подвал', keys: ['footer'] },
  { n: 6, name: 'Хэштеги', keys: ['hashtags'] },
  { n: 7, name: 'Теги', keys: ['tags'] },
  { n: 8, name: 'Закреплённый комментарий', keys: ['pinnedComment'] },
];
// Пункты, которые можно осознанно оставить пустыми (например, гайд без оверлея).
const TB_CAN_BE_EMPTY = [1, 8];

function tbEmptyState() {
  return {
    v: 1,
    items: { overlayText: '', overlayPosition: '', title: '', description: '', timecodes: [], footer: '', hashtags: '', tags: '', pinnedComment: '' },
    set: {},
    agreed: {},
    descriptionEN: '',
    descriptionENFor: '',
    seenImages: [],
    ru: {},
  };
}

function tbParseState(raw) {
  const s = tbEmptyState();
  if (!raw) return s;
  let p;
  try { p = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { return s; }
  if (!p || typeof p !== 'object') return s;
  Object.assign(s.items, p.items || {});
  if (!Array.isArray(s.items.timecodes)) s.items.timecodes = [];
  s.set = p.set || {};
  s.agreed = p.agreed || {};
  s.descriptionEN = p.descriptionEN || '';
  s.descriptionENFor = p.descriptionENFor || '';
  s.seenImages = Array.isArray(p.seenImages) ? p.seenImages : [];
  s.ru = (p.ru && typeof p.ru === 'object') ? p.ru : {};
  return s;
}

function tbAllAgreed(s) {
  return TB_ITEMS.every(it => s.agreed[it.n] === true);
}

function tbPositionRu(p) {
  return { left: 'слева', right: 'справа', center: 'по центру' }[String(p || '').toLowerCase()] || (p || '');
}

// Текст одного пункта для показа автору (без номера и названия).
// Русский перевод (state.ru) показывается рядом в скобках — только автору;
// в таблицу и на YouTube уходит лишь сам текст пункта (state.items).
function tbItemText(s, n) {
  const it = s.items;
  const ru = s.ru || {};
  const tr = (v) => (v ? ` (${v})` : '');
  switch (n) {
    case 1:
      if (!s.set[1]) return '';
      return it.overlayText ? `${it.overlayText}${tr(ru.overlayText)} — ${tbPositionRu(it.overlayPosition) || 'позиция не указана'}` : '— без оверлея';
    case 2: return it.title ? it.title + tr(ru.title) : '';
    case 3: return (it.description || '') + (it.description && ru.description ? `\n\n— Перевод для автора —\n${ru.description}` : '');
    case 4: return (it.timecodes || []).map((t, i) => `${i + 1}. ${t}${tr((ru.timecodes || [])[i])}`).join('\n');
    case 5: return it.footer || '';
    case 6: return it.hashtags || '';
    case 7: return it.tags || '';
    case 8:
      if (!s.set[8]) return '';
      return it.pinnedComment ? it.pinnedComment + (ru.pinnedComment ? `\n(${ru.pinnedComment})` : '') : '— без закреплённого комментария';
  }
  return '';
}

function escapeHtml(t) {
  return String(t == null ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// Режем длинный текст на куски под лимит Телеграма (4096), стараясь по переносу строки.
function splitForTelegram(text, limit) {
  const LIMIT = limit || 3800;
  const chunks = [];
  let rest = String(text || '');
  while (rest.length > LIMIT) {
    let cut = rest.lastIndexOf('\n', LIMIT);
    if (cut < LIMIT * 0.5) cut = LIMIT;
    chunks.push(rest.slice(0, cut));
    rest = rest.slice(cut).replace(/^\n+/, '');
  }
  if (rest.length) chunks.push(rest);
  if (!chunks.length) return [''];
  // ID проекта — в КАЖДОЙ части: автор может ответить (reply) на любую.
  const idm = String(text || '').match(/\n\nID: (\S+)\s*$/);
  if (idm && chunks.length > 1) {
    for (let i = 0; i < chunks.length - 1; i++) chunks[i] += `\n\n(продолжение ниже)\nID: ${idm[1]}`;
  }
  return chunks;
}

function findByLabel(row, label) {
  const key = Object.keys(row || {}).find(k => k.replace(/^[^a-zA-Z]+/, '') === label);
  return key ? row[key] : undefined;
}

// Барьер перед сборщиком: проверяем то, что РЕАЛЬНО лежит в таблице (строку
// перечитываем заново перед проверкой), а не то, что мы "вроде бы записали".
function validateForAssembler(row, tmpl, opts) {
  const o = opts || {};
  const problems = [];
  const val = k => String(row[k] == null ? '' : row[k]).trim();

  let required = ['overlayPosition', 'title', 'hashtags', 'tags', 'description'];
  const rawReq = findByLabel(tmpl, 'tmpl_RequiredTechFields');
  if (rawReq && String(rawReq).trim()) {
    required = String(rawReq).split(',').map(x => x.trim()).filter(Boolean);
  }
  const colFor = {
    overlayText: 'ai_OverlayText', overlayPosition: 'ai_OverlayPosition', title: 'ai_Title',
    hashtags: 'ai_Hashtags', tags: 'ai_Tags', description: 'ai_Description', pinnedComment: 'ai_PinnedComment',
  };
  for (const key of required) {
    const col = colFor[key] || key;
    if (!val(col)) problems.push(`${col} пустая`);
  }
  if (!val('ai_ApprovedImageUrl')) problems.push('ai_ApprovedImageUrl пустая (нет согласованной картинки)');
  if (!val('ai_DescriptionEN')) problems.push('ai_DescriptionEN пустая (нет английского описания)');
  if (val('ai_Description') && !/\[?Timecodes\]?/i.test(val('ai_Description'))) {
    problems.push('в ai_Description нет метки [Timecodes]');
  }
  if (o.needApproved && val('sys_Status') !== 'Утверждено') {
    problems.push(`статус «${val('sys_Status') || 'пусто'}», а не «Утверждено»`);
  }
  if (o.needTracks && !val('sys_AudioZipUrl')) problems.push('sys_AudioZipUrl пустая (нет ссылки на треки)');
  return problems;
}
// ── конец общего куска ─────────────────────────────────────────────────────

// Задание Писателю: только то, что нужно для истории. Правила, голос и мир
// Пингви — из таблицы; бланка на 8 пунктов и прежнего черновика здесь нет.
const b = $('Разбираем ответ редактора').first().json;
const ctx = $('Контекст проекта').first().json;
const kb = $('Собираем знания канала').first().json;
let prevText = '';
try { prevText = $('Прошлые главы').first().json.text || ''; } catch (e) {}
const row = ctx.row || {};
const state = tbParseState(b.editorState);
const approvedUrl = b.resolvedApprovedImageUrl || String(row.ai_ApprovedImageUrl || '').trim();

const instructions = [
  `Ты — писатель канала "${ctx.sheetName}". Ты пишешь описание выпуска — историю к согласованной картинке. Правила, голос и мир героя — ниже, из таблицы канала. Ответь только текстом истории, без заголовка и пояснений.`,
  kb.writerRules ? 'ПРАВИЛА ОПИСАНИЯ:\n' + kb.writerRules : '',
  kb.writerWorld || '',
  prevText ? 'ПРОШЛЫЕ ГЛАВЫ — последние выпуски канала, как их согласовала автор (для продолжения голоса и сквозных нитей; сюжеты не повторяй):\n' + prevText : '',
].filter(Boolean).join('\n\n');

let task = 'ЗАДАНИЕ ОТ РЕДАКТОРА:\n' + b.storyBrief;
if (row.ai_UserBrief) task += '\n\nИзначальный бриф автора: ' + row.ai_UserBrief;
if (b.storyKeep && state.items.description) {
  task += '\n\nИз прежнего текста автор похвалила: ' + b.storyKeep +
    '\n\nПрежний текст — только чтобы взять похваленное, остальное пиши заново:\n' + state.items.description;
}
const content = [{ type: 'input_text', text: task }];
if (approvedUrl) {
  content.push({ type: 'input_text', text: '(Согласованная картинка выпуска:)' });
  content.push({ type: 'input_image', image_url: approvedUrl });
}

return [{
  json: {
    requestBody: {
      model: 'gpt-5',
      reasoning: { effort: 'high' },
      instructions,
      input: [{ role: 'user', content }],
    },
  },
}];

// Автор читает описание в переводе на русский; правила перевода — из таблицы (###ПЕРЕВОД###).
const kb = $('Собираем знания канала').first().json;
const r = $input.first().json || {};
const story = (r.output || [])
  .filter(i => i.type === 'message')
  .flatMap(i => (i.content || []).filter(c => c.type === 'output_text').map(c => c.text))
  .join('\n\n')
  .trim();
const rules = kb.translationRules ? '\n\nПравила перевода канала:\n' + kb.translationRules : '';
return [{
  json: {
    requestBody: {
      model: 'gpt-5',
      input: [
        { role: 'system', content: 'Переведи этот текст на русский для автора канала. Ответь только переводом.' + rules },
        { role: 'user', content: story || '(пусто)' },
      ],
    },
  },
}];

