// сообщения (после кнопки "✅" подтверждение уже отправлено отдельно).
const approvedLine = p.approvedNow && !p.fromButton
  ? `✅ Картинка согласована${p.approveVariantNumber ? ' (вариант ' + p.approveVariantNumber + ')' : ''}.\n\n`
  : '';

